<?php if(!defined('APP_ENTRY'))exit; $table=$user['role']==='student'?'student_accounts':'staff_accounts'; if($_SERVER['REQUEST_METHOD']==='POST')try{$new=password_field('new_password');if($new!==post('confirm_password'))throw new DomainException('New passwords do not match.');transaction(function()use($table,$user,$new){$a=one("SELECT password_hash FROM $table WHERE id=? FOR UPDATE",[$user['id']]);if(!$a||!password_verify(post('current_password'),$a['password_hash']))throw new DomainException('Current password is incorrect.');execute("UPDATE $table SET password_hash=?,session_version=session_version+1 WHERE id=?",[password_hash($new,PASSWORD_DEFAULT),$user['id']]);audit('password changed','own account');});logout_user();redirect('login');}catch(DomainException $ex){$error=$ex->getMessage();}catch(PDOException $ex){error_log_file($ex);$error='Password could not be changed.';}$profile=$user['role']==='student'?one('SELECT s.name,s.email,s.age,s.gender,s.address,s.contact_number,s.year_level,c.course_name FROM students s JOIN courses c ON c.id=s.course_id WHERE s.id=?',[$user['student_id']]):['name'=>$user['name'],'role'=>$user['role']]; ?>
<?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><section class="panel"><h2>Account information</h2><p class="muted">Username: <?=e($user['username'])?></p><div class="grid-form"><?php foreach($profile as $k=>$v):?><div><small class="muted"><?=e(ucwords(str_replace('_',' ',$k)))?></small><p><?=e($v)?></p></div><?php endforeach;?></div></section><section class="panel"><h2>Change password</h2><form method="post" class="grid-form"><?=csrf_field()?><label>Current password<input type="password" name="current_password" required></label><label>New password<input type="password" name="new_password" minlength="10" maxlength="72" required></label><label>Confirm new password<input type="password" name="confirm_password" minlength="10" maxlength="72" required></label><div class="form-actions"><button>Change password and sign out</button></div></form></section>
